 let hash=Hash{answer,left:if left{&values[15]}else{&sibling},right:if left{&sibling}else{&values[15]},coordinate:c,calls:&calls};
 assert_eq!(sibling_binary_parent(hash,&values,15,&sibling,left)[c],answer[c]);assert_eq!(calls.get(),1);
}

fn NBE_offset(){
 let at:usize=kani::any();let i:usize=kani::any();kani::assume(at<=57607 && i<6);
 let (next,j)=NBE_offset_step(at,i);
 let cap=match i{0=>146,1=>146,2=>128,3=>172,4=>172,_=>150};
 assert_eq!(next,at+32*cap);assert_eq!(j,i+1);
}

fn NBI_sibling_window(){
 let nodes:[u8;5504]=kani::any();let at:usize=kani::any();let len:usize=kani::any();let c:usize=kani::any();
 kani::assume(at<=len && len<=5504 && c<32);
 let selected=nodes[..len].get(at..at+32);
 if len-at<32{assert!(selected.is_none())}else{
  let sibling=selected.unwrap();assert_eq!(sibling.len(),32);assert_eq!(sibling.as_ptr(),nodes[at..].as_ptr());
  assert_eq!(sibling[c],nodes[at+c]);
 }
}

fn NBI_index_write(){
 let mut idx:[u32;16]=kani::any();let old=idx;let w:usize=kani::any();let i:usize=kani::any();let k:usize=kani::any();
 kani::assume(w<=i && i<16 && k<16);let parent=index_at(&idx,i)>>Arity::Two.bits();
 idx[w]=parent;
 assert_eq!(idx[k],if k==w{old[i]/2}else{old[k]});
}

fn NBI_supplied_cursors(){
 let mut at:usize=kani::any();let mut i:usize=kani::any();let mut w:usize=kani::any();let len:usize=kani::any();let n:usize=kani::any();
 kani::assume(n>0 && n<=16 && w<=i && i<n && at<=len && len<=5504 && len-at>=32);
 let (a,b,c)=(at,i,w);at+=32;i+=1;w+=1;
 assert_eq!((at,i,w),(a+32,b+1,c+1));assert!(at<=len && w<=i && i<=n);
}

fn NBI_count_scan_step(){
 let level:[u32;16]=kani::any();let n:usize=kani::any();let i:usize=kani::any();let mut j:usize=kani::any();
 kani::assume(i<=j && j<=n && n<=16 && i<n);let parent=index_at(&level,i)>>Arity::Two.bits();let before=j;
 if j<n && index_at(&level,j)>>Arity::Two.bits()==parent{j+=1;assert!(j<=n);assert_eq!(level[before]/2,parent)}else{assert_eq!(j,before)}
 assert!(j==before || j==before+1);
}

fn NBI_count_commit(){
 let mut level:[u32;16]=kani::any();let old=level;let n:usize=kani::any();let mut w:usize=kani::any();let mut i:usize=kani::any();let j:usize=kani::any();let mut count:usize=kani::any();let k:usize=kani::any();
 kani::assume(w<=i && i<j && j<=n && n<=16 && j-i<=2 && count<=288 && k<16);
 let parent=index_at(&level,i)>>Arity::Two.bits();let (ow,oc,oi)=(w,count,i);
 count+=Arity::Two.width()-(j-i);level[w]=parent;w+=1;i=j;
 assert_eq!(count,oc+2-(j-oi));
 assert_eq!(level[k],if k==ow{parent}else{old[k]});assert!(w<=i && i<=n);
}

